func TestEvalFilterTodos(t *testing.T) {
    handler := newAPIHandler(newTestStore(t))
    performRequest[Todo](t, handler, http.MethodPost, "/api/todos", `{"title":"open"}`, http.StatusCreated)
    performRequest[Todo](t, handler, http.MethodPost, "/api/todos", `{"title":"done","completed":true}`, http.StatusCreated)
    complete := performRequest[[]Todo](t, handler, http.MethodGet, "/api/todos?completed=true", "", http.StatusOK)
    if len(complete) != 1 || complete[0].Title != "done" {
        t.Fatalf("completed filter = %+v", complete)
    }
    open := performRequest[[]Todo](t, handler, http.MethodGet, "/api/todos?completed=false", "", http.StatusOK)
    if len(open) != 1 || open[0].Title != "open" {
        t.Fatalf("open filter = %+v", open)
    }
    invalid := httptest.NewRecorder()
    handler.ServeHTTP(invalid, httptest.NewRequest(http.MethodGet, "/api/todos?completed=maybe", nil))
    if invalid.Code != http.StatusBadRequest {
        t.Fatalf("invalid filter status = %d, want 400", invalid.Code)
    }
}

import { LitElement, css, html } from 'lit';
import { todoAPI } from './api.js';

export class TodoApp extends LitElement {
  static properties = {
    todos: { state: true },
    newTitle: { state: true },
    editingId: { state: true },
    editTitle: { state: true },
    loading: { state: true },
    error: { state: true },
  };

  static styles = css`
    :host {
      color: #243024;
      display: block;
      font-family: Inter, ui-sans-serif, system-ui, sans-serif;
      min-height: 100vh;
      background:
        radial-gradient(circle at top left, #f6df9f 0, transparent 36rem),
        #f7f5ed;
    }

    * { box-sizing: border-box; }

    main {
      margin: 0 auto;
      max-width: 760px;
      padding: 72px 24px;
    }

    .eyebrow {
      color: #557052;
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.14em;
      margin: 0 0 10px;
      text-transform: uppercase;
    }

    h1 {
      font-family: Georgia, serif;
      font-size: clamp(2.6rem, 8vw, 4.8rem);
      font-weight: 500;
      letter-spacing: -0.05em;
      line-height: 0.95;
      margin: 0;
    }

    .subtitle {
      color: #637061;
      font-size: 1.05rem;
      margin: 18px 0 34px;
    }

    form, li {
      align-items: center;
      background: rgba(255, 255, 255, 0.82);
      border: 1px solid #dfe2d7;
      border-radius: 16px;
      display: flex;
      gap: 12px;
      padding: 12px;
      box-shadow: 0 8px 30px rgba(46, 63, 43, 0.06);
    }

    input[type='text'] {
      background: transparent;
      border: 0;
      color: inherit;
      flex: 1;
      font: inherit;
      min-width: 0;
      outline: none;
      padding: 9px 10px;
    }

    input[type='text']:focus { box-shadow: inset 0 -2px #6a8865; }

    button {
      background: #304f35;
      border: 0;
      border-radius: 10px;
      color: white;
      cursor: pointer;
      font: inherit;
      font-weight: 700;
      padding: 10px 15px;
    }

    button.secondary {
      background: #edf0e9;
      color: #435443;
    }

    button:focus-visible, input:focus-visible {
      outline: 3px solid #e0ad33;
      outline-offset: 2px;
    }

    ul {
      display: grid;
      gap: 10px;
      list-style: none;
      margin: 20px 0 0;
      padding: 0;
    }

    li.completed .title {
      color: #879084;
      text-decoration: line-through;
    }

    .title { flex: 1; padding: 0 4px; }
    .empty, .loading { color: #6e786c; padding: 34px 12px; text-align: center; }
    .error { color: #8e2f29; margin: 12px 4px; }

    @media (max-width: 560px) {
      main { padding-top: 46px; }
      li { align-items: stretch; flex-wrap: wrap; }
      li .title { flex-basis: calc(100% - 40px); }
    }
  `;

  constructor() {
    super();
    this.todos = [];
    this.newTitle = '';
    this.editingId = null;
    this.editTitle = '';
    this.loading = true;
    this.error = '';
  }

  connectedCallback() {
    super.connectedCallback();
    this.loadTodos();
  }

  async loadTodos() {
    this.loading = true;
    this.error = '';
    try {
      this.todos = await todoAPI.list();
    } catch (error) {
      this.error = error.message;
    } finally {
      this.loading = false;
    }
  }

  async createTodo(event) {
    event.preventDefault();
    if (!this.newTitle.trim()) return;

    this.error = '';
    try {
      const todo = await todoAPI.create(this.newTitle);
      this.todos = [...this.todos, todo];
      this.newTitle = '';
    } catch (error) {
      this.error = error.message;
    }
  }

  startEditing(todo) {
    this.editingId = todo.id;
    this.editTitle = todo.title;
  }

  cancelEditing() {
    this.editingId = null;
    this.editTitle = '';
  }

  async saveEdit(todo) {
    if (!this.editTitle.trim()) return;
    await this.saveTodo({ ...todo, title: this.editTitle });
    this.cancelEditing();
  }

  async toggleTodo(todo) {
    await this.saveTodo({ ...todo, completed: !todo.completed });
  }

  async saveTodo(todo) {
    this.error = '';
    try {
      const updated = await todoAPI.update(todo);
      this.todos = this.todos.map((item) => item.id === updated.id ? updated : item);
    } catch (error) {
      this.error = error.message;
    }
  }

  renderTodo(todo) {
    const editing = this.editingId === todo.id;
    return html`
      <li class=${todo.completed ? 'completed' : ''}>
        <input
          type="checkbox"
          aria-label="Mark ${todo.title} complete"
          .checked=${todo.completed}
          @change=${() => this.toggleTodo(todo)}
        />
        ${editing
          ? html`
              <input
                type="text"
                aria-label="Edit todo title"
                .value=${this.editTitle}
                @input=${(event) => { this.editTitle = event.target.value; }}
              />
              <button @click=${() => this.saveEdit(todo)}>Save</button>
              <button class="secondary" @click=${this.cancelEditing}>Cancel</button>
            `
          : html`
              <span class="title">${todo.title}</span>
              <button class="secondary" @click=${() => this.startEditing(todo)}>Edit</button>
            `}
      </li>
    `;
  }

  render() {
    return html`
      <main>
        <p class="eyebrow">A tiny full-stack benchmark</p>
        <h1>Small wins.</h1>
        <p class="subtitle">Keep the next thing clear and the finished things visible.</p>

        <form @submit=${this.createTodo}>
          <input
            type="text"
            aria-label="New todo title"
            placeholder="What needs doing?"
            .value=${this.newTitle}
            @input=${(event) => { this.newTitle = event.target.value; }}
          />
          <button type="submit">Add todo</button>
        </form>

        ${this.error ? html`<p class="error" role="alert">${this.error}</p>` : ''}
        ${this.loading
          ? html`<p class="loading">Loading todos…</p>`
          : this.todos.length
            ? html`<ul>${this.todos.map((todo) => this.renderTodo(todo))}</ul>`
            : html`<p class="empty">Nothing here yet. Add one small win.</p>`}
      </main>
    `;
  }
}

